{
  "name": "chuskybrowser-mcp",
  "version": "1.19.0",
  "description": "Standalone stdio MCP server exposing the chuskybrowser REST API as MCP tools (Claude Code, Codex, agy, Cursor, opencode). Proxies to an already-running chuskybrowser REST server — does not itself require the browser binary, Playwright, or the core server's dependencies. Initial MCP implementation contributed by @epicsagas.",
  "type": "module",
  "main": "server.mjs",
  "license": "MIT",
  "author": "Seyyid Annan <seyyid236@gmail.com>",
  "homepage": "https://github.com/zester4/chuskybrowser/tree/master/mcp#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/zester4/chuskybrowser.git",
    "directory": "mcp"
  },
  "bugs": {
    "url": "https://github.com/zester4/chuskybrowser/issues"
  },
  "keywords": [
    "mcp",
    "model-context-protocol",
    "chusky",
    "camoufox",
    "browser-automation",
    "claude-code",
    "codex",
    "cursor",
    "opencode"
  ],
  "engines": {
    "node": ">=22"
  },
  "bin": {
    "chuskybrowser-mcp": "server.mjs"
  },
  "files": [
    "server.mjs",
    "lib/",
    "README.md"
  ],
  "dependencies": {
    "@modelcontextprotocol/sdk": "^1.30.0"
  },
  "overrides": {
    "fast-uri": "3.1.8",
    "hono": "4.13.7",
    "qs": "6.16.0"
  }
}
